using System.Text.Json.Serialization;

namespace Azure.ResourceManager
{
    internal sealed class ResponseErrorAotConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var doc = JsonDocument.ParseValue(ref reader);
            return ParseError(doc.RootElement);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code"u8, value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message"u8, value.Message);
            }
            if (value.Target != null)
            {
                writer.WriteString("target"u8, value.Target);
            }
            if (value.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, value.InnerError);
            }
            if (value.Details is { Count: > 0 })
            {
                writer.WritePropertyName("details"u8);
                writer.WriteStartArray();
                foreach (var detail in value.Details)
                {
                    Write(writer, detail, options);
                }
                writer.WriteEndArray();
            }
            writer.WriteEndObject();
        }

        private static void WriteInnerError(Utf8JsonWriter writer, ResponseInnerError error)
        {
            writer.WriteStartObject();
            if (error.Code != null)
            {
                writer.WriteString("code"u8, error.Code);
            }
            if (error.InnerError != null)
            {
                writer.WritePropertyName("innererror"u8);
                WriteInnerError(writer, error.InnerError);
            }
            writer.WriteEndObject();
        }

        private static ResponseError ParseError(JsonElement element)
        {
            string code = null, message = null, target = null;
            List<ResponseError> details = null;

            if (element.TryGetProperty("code"u8, out var c))
            {
                code = c.GetString();
            }
            if (element.TryGetProperty("message"u8, out var m))
            {
                message = m.GetString();
            }
            if (element.TryGetProperty("target"u8, out var t))
            {
                target = t.GetString();
            }
            if (element.TryGetProperty("details"u8, out var d) && d.ValueKind == JsonValueKind.Array)
            {
                details = new List<ResponseError>();
                foreach (var item in d.EnumerateArray())
                {
                    details.Add(ParseError(item));
                }
            }

            return new ResponseError(code, message, target, element.Clone(), null, details);
        }
    }
}

